private function ratePart(Cost $ratePerMillion, int $tokenCount): Cost
{
    if ($tokenCount === 0) {
        return Cost::zero();
    }

    // tokens × rate / 1 000 000 — точное десятичное деление.
    return new Cost(bcdiv(bcmul($ratePerMillion->toSixDecimals(), (string) $tokenCount, 20), '1000000', 20));
}

