public function isNegative(): bool
{
    return bccomp($this->decimal, '0', self::SCALE) < 0;
}

/**
 * Внутреннее точное десятичное представление.
 */
public function decimal(): string
{
    return $this->decimal;
}

/**
 * HALF_UP-округление до 6 знаков после точки (без float).
 */
public static function roundHalfUp6(self $value): string
{
    // Дробная шестая цифра: 10-я цифра после точки (масштаб 20).
    $tail = str_pad(substr($value->decimal(), strpos($value->decimal(), '.') + 1), 20, '0');
    $sixthDigit = (int) $tail[5];
    $roundFraction = $value->isNegative() ? '0.0000005' : '0.0000005';

    // HALF_UP для отрицательных величин — дальше от нуля.
    $shifted = $value->isNegative()
        ? bcsub($value->decimal(), $roundFraction, 20)
        : bcadd($value->decimal(), $roundFraction, 20);

    return bcadd($shifted, '0', 6);
}

